contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount == 10, "amount must equal TICKET_AMOUNT");
        require(address(this).balance >= amount, "insufficient balance");

        uint potBefore = c.pot();
        address bankBefore = c.bank();
        uint contractBalanceBefore = address(c).balance;
        uint selfBalanceBefore = address(this).balance;

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint potAfter = c.pot();
            uint selfBalanceAfter = address(this).balance;
            bool paidPayout = (potAfter == 0);
            bool keptPot = (potAfter == potBefore + amount);

            if (paidPayout) {
                // bank receives FEE_AMOUNT, player receives potBefore + amount - FEE_AMOUNT
                assert(selfBalanceAfter == selfBalanceBefore - amount + (potBefore + amount - 1));
                assert(address(bankBefore).balance >= 1);
            } else if (keptPot) {
                // no payout and no fee transfer
                assert(selfBalanceAfter == selfBalanceBefore - amount);
            } else {
                assert(false);
            }
        } else {
            assert(c.pot() == potBefore);
            assert(address(c).balance == contractBalanceBefore);
            assert(address(this).balance == selfBalanceBefore - amount);
        }
    }

    receive() external payable {}
}

